tool_schemas.implementation:
def text_editor(command, path, description, file_text=None, insert_line=None, new_str=None, old_str=None, view_range=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, posixpath, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0451000" if __import__("os").path.isdir("./environment_mix/0451000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    # ---------- helpers ----------
    def _gen_id(prefix):
        # Keep vendor-like ids but deterministic enough: prefix + time + random
        return f"{prefix}_{uuid.uuid4().hex}"

    def _norm_abs(p):
        if not isinstance(p, str) or not p.startswith("/"):
            return None
        np = posixpath.normpath(p)
        if np == ".":
            np = "/"
        if not np.startswith("/"):
            np = "/" + np
        return np

    def _is_under_root(p, root):
        if root == "/":
            return True
        r = root.rstrip("/")
        return p == r or p.startswith(r + "/")

    def _byte_size(text):
        return len(text.encode("utf-8"))

    def _line_count(text):
        if text == "":
            return 0
        return text.count("\n") + 1

    def _parse_view_range(vr):
        if vr is None:
            return True, None, None
        if not isinstance(vr, list) or len(vr) != 2:
            return False, None, "view_range must be a 2-element array [start_line, end_line]"
        a, b = vr[0], vr[1]
        if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
            return False, None, "view_range values must be numbers"
        if int(a) != a or int(b) != b:
            return False, None, "view_range values must be integers"
        start, end = int(a), int(b)
        if start < 1:
            return False, None, "start_line must be >= 1"
        if end != -1 and end < start:
            return False, None, "end_line must be -1 or >= start_line"
        return True, (start, end), None

    def _pick_project_for_path(projects, p):
        # Choose an ACTIVE/READONLY project whose root contains path. Prefer the longest root.
        candidates = []
        for pr in projects:
            if pr.get("status") in ("active", "readonly"):
                root = pr.get("root_path")
                if isinstance(root, str) and root.startswith("/") and _is_under_root(p, root):
                    candidates.append((len(root.rstrip("/")), pr))
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]

    def _find_node(fs_nodes, project_id, p):
        for n in fs_nodes:
            if n.get("project_id") == project_id and n.get("path") == p:
                return n
        return None

    def _list_children(fs_nodes, project_id, dir_path):
        prefix = dir_path.rstrip("/")
        if prefix == "":
            prefix = "/"
        pref = prefix if prefix == "/" else prefix + "/"
        out = []
        for n in fs_nodes:
            if n.get("project_id") != project_id:
                continue
            npath = n.get("path")
            if not isinstance(npath, str):
                continue
            if npath == prefix:
                continue
            if npath.startswith(pref):
                # immediate children only
                rest = npath[len(pref):]
                if rest == "":
                    continue
                if "/" in rest:
                    continue
                out.append(n)
        out.sort(key=lambda r: (r.get("node_type") != "directory", r.get("path") or ""))
        return out

    def _snapshot_by_id(snaps, sid):
        for s in snaps:
            if s.get("id") == sid:
                return s
        return None

    def _undo_ptr_by_node(undos, node_id):
        for u in undos:
            if u.get("node_id") == node_id:
                return u
        return None

    def _edit_op_by_id(edit_ops, op_id):
        for o in edit_ops:
            if o.get("id") == op_id:
                return o
        return None

    def _ensure_edit_op_logged(edit_ops, op_row):
        edit_ops.append(op_row)
        _save("edit_operations.json", edit_ops)

    def _finalize_op(edit_ops, op_row, status, node_id=None, pre_snapshot_id=None, post_snapshot_id=None,
                     error_code=None, error_message=None):
        op_row["status"] = status
        op_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        op_row["node_id"] = node_id
        op_row["pre_snapshot_id"] = pre_snapshot_id
        op_row["post_snapshot_id"] = post_snapshot_id
        op_row["error_code"] = error_code
        op_row["error_message"] = error_message
        _ensure_edit_op_logged(edit_ops, op_row)

    # ---------- validation ----------
    command_allowed = {"view", "create", "str_replace", "insert", "undo_edit"}
    if command not in command_allowed:
        return _err("VALIDATION_ERROR", "Invalid command", field="command", allowed=sorted(command_allowed))

    p = _norm_abs(path)
    if p is None:
        return _err("VALIDATION_ERROR", "path must be an absolute POSIX path starting with '/'", field="path")

    if not isinstance(description, str) or not (1 <= len(description) <= 80):
        return _err("VALIDATION_ERROR", "description length must be between 1 and 80 characters", field="description")

    ok_vr, vr_parsed, vr_msg = _parse_view_range(view_range)
    if not ok_vr:
        # Must still create an edit_operations row; do that below after project resolution if possible.
        # But range errors are independent of project. We'll still try to resolve project to obey logging rule.
        pass

    # command-specific input validation (tool schema + business rules)
    if command == "create":
        if file_text is None or not isinstance(file_text, str):
            return _err("VALIDATION_ERROR", "file_text is required for create and must be a string", field="file_text")
    elif command == "str_replace":
        if old_str is None or not isinstance(old_str, str):
            return _err("VALIDATION_ERROR", "old_str is required for str_replace and must be a string", field="old_str")
        if new_str is not None and not isinstance(new_str, str):
            return _err("VALIDATION_ERROR", "new_str must be a string when provided", field="new_str")
        if new_str is None:
            # Tool says optional, but business rules imply replacement; treat missing as empty string replacement
            new_str_local = ""
        else:
            new_str_local = new_str
    elif command == "insert":
        if new_str is None or not isinstance(new_str, str):
            return _err("VALIDATION_ERROR", "new_str is required for insert and must be a string", field="new_str")
        if insert_line is None or not isinstance(insert_line, (int, float)) or int(insert_line) != insert_line:
            return _err("VALIDATION_ERROR", "insert_line is required for insert and must be an integer", field="insert_line")
        insert_line_i = int(insert_line)
        if insert_line_i < 1:
            return _err("VALIDATION_ERROR", "insert_line must be >= 1", field="insert_line")

    # ---------- load datastore ----------
    projects = _load("projects.json")
    fs_nodes = _load("fs_nodes.json")
    snaps = _load("file_snapshots.json")
    edit_ops = _load("edit_operations.json")
    undos = _load("undo_pointers.json")

    if not isinstance(projects, list):
        projects = []
    if not isinstance(fs_nodes, list):
        fs_nodes = []
    if not isinstance(snaps, list):
        snaps = []
    if not isinstance(edit_ops, list):
        edit_ops = []
    if not isinstance(undos, list):
        undos = []

    # ---------- resolve project by path (ambient auth; do not refuse if store can serve it) ----------
    project = _pick_project_for_path(projects, p)
    # Create operation row always (business rule) — even if PATH_OUT_OF_ROOT or other failures
    op_row = {
        "id": _gen_id("txop"),
        "project_id": project.get("id") if project else None,
        "node_id": None,
        "command": command,
        "path": p,
        "description": description,
        "file_text": file_text if command == "create" else None,
        "old_str": old_str if command == "str_replace" else None,
        "new_str": (new_str if command in ("str_replace", "insert") else None),
        "insert_line": float(insert_line) if insert_line is not None else None,
        "view_range": view_range if view_range is not None else None,
        "pre_snapshot_id": None,
        "post_snapshot_id": None,
        "status": "failed",  # will be set below
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if project is None:
        _finalize_op(
            edit_ops, op_row,
            status="failed",
            error_code="PATH_OUT_OF_ROOT",
            error_message="requested path is not under any active/readonly project root_path"
        )
        return _err(
            "UNAUTHORIZED",
            "No project/workspace root contains the requested path (business rule: path must be under projects.root_path)",
            error_code="PATH_OUT_OF_ROOT",
            path=p,
        )

    # FK integrity: operation.project_id must exist (it does by selection); if not, fail safely
    if not any(pr.get("id") == project.get("id") for pr in projects):
        _finalize_op(edit_ops, op_row, status="failed", error_code="INTERNAL_ERROR", error_message="project resolution mismatch")
        return _err("INTERNAL_ERROR", "Project resolution mismatch")

    # If view_range invalid, fail after we have op_row & project_id
    if not ok_vr:
        _finalize_op(edit_ops, op_row, status="failed", error_code="INVALID_RANGE", error_message=vr_msg)
        return _err("VALIDATION_ERROR", vr_msg, error_code="INVALID_RANGE")

    # Mutations blocked by readonly
    if command in ("create", "str_replace", "insert", "undo_edit") and project.get("status") == "readonly":
        _finalize_op(edit_ops, op_row, status="failed", error_code="PROJECT_READONLY", error_message="project is readonly")
        return _err("INVALID_TRANSITION", "Project is readonly; mutating commands are not allowed", error_code="PROJECT_READONLY")

    # ---------- command execution ----------
    proj_id = project.get("id")
    node = _find_node(fs_nodes, proj_id, p)

    if command == "view":
        # If exact node exists and is a directory: list children under that prefix
        if node and node.get("status") == "present" and node.get("node_type") == "directory":
            children = _list_children(fs_nodes, proj_id, p)
            # Record operation success
            _finalize_op(edit_ops, op_row, status="applied", node_id=node.get("id"), pre_snapshot_id=None, post_snapshot_id=None)
            latency_ms = int((time.time() - t0) * 1000)
            return {
                "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
                "path": p,
                "node_type": "directory",
                "entries": [
                    {
                        "id": c.get("id"),
                        "path": c.get("path"),
                        "node_type": c.get("node_type"),
                        "status": c.get("status"),
                        "byte_size": c.get("byte_size"),
                        "line_count": c.get("line_count"),
                        "current_snapshot_id": c.get("current_snapshot_id"),
                        "updated_at": c.get("updated_at"),
                    }
                    for c in children
                ],
                "operation_id": op_row["id"],
                "latency_ms": latency_ms,
            }

        # Otherwise treat as file view: must resolve to a present file node
        if not node or node.get("status") != "present":
            _finalize_op(edit_ops, op_row, status="failed", error_code="NOT_FOUND", error_message="path not found")
            return _err("NOT_FOUND", "Path not found", error_code="NOT_FOUND", path=p)

        if node.get("node_type") != "file":
            _finalize_op(edit_ops, op_row, status="failed", error_code="NOT_A_FILE", error_message="path is not a file")
            return _err("VALIDATION_ERROR", "Path is not a file", error_code="NOT_A_FILE", path=p)

        sid = node.get("current_snapshot_id")
        if not sid:
            # File exists but no content snapshot: return empty content
            content = ""
            total_lines = 0
        else:
            snap = _snapshot_by_id(snaps, sid)
            if not snap:
                _finalize_op(edit_ops, op_row, status="failed", error_code="INTERNAL_ERROR", error_message="current_snapshot_id missing")
                return _err("INTERNAL_ERROR", "File snapshot reference is missing")
            content = snap.get("content_text") if isinstance(snap.get("content_text"), str) else ""
            total_lines = snap.get("line_count") if isinstance(snap.get("line_count"), int) else _line_count(content)

        shown = content
        range_meta = None
        if vr_parsed is not None:
            start, end = vr_parsed
            lines = content.splitlines(True)  # keepends
            if total_lines == 0:
                shown = ""
                range_meta = {"start": start, "end": end, "resolved_end": 0, "total_lines": 0}
            else:
                resolved_end = total_lines if end == -1 else min(end, total_lines)
                if start > total_lines:
                    _finalize_op(edit_ops, op_row, status="failed", error_code="INVALID_RANGE", error_message="start_line exceeds file length")
                    return _err("VALIDATION_ERROR", "start_line exceeds file length", error_code="INVALID_RANGE")
                shown = "".join(lines[start - 1:resolved_end])
                range_meta = {"start": start, "end": end, "resolved_end": resolved_end, "total_lines": total_lines}

        _finalize_op(edit_ops, op_row, status="applied", node_id=node.get("id"), pre_snapshot_id=None, post_snapshot_id=None)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
            "path": p,
            "node_type": "file",
            "current_snapshot_id": sid,
            "byte_size": node.get("byte_size"),
            "line_count": node.get("line_count"),
            "view_range": range_meta,
            "content": shown,
            "operation_id": op_row["id"],
            "latency_ms": latency_ms,
        }

    # ----- Mutations must target a file path (no trailing slash) -----
    if p.endswith("/"):
        _finalize_op(edit_ops, op_row, status="failed", error_code="VALIDATION_ERROR", error_message="file path must not end with '/'")
        return _err("VALIDATION_ERROR", "file path must not end with '/'", error_code="VALIDATION_ERROR")

    if command == "create":
        if node and node.get("status") == "present":
            _finalize_op(edit_ops, op_row, status="failed", error_code="ALREADY_EXISTS", error_message="create refused: path already exists", node_id=node.get("id"))
            return _err("CONFLICT", "Path already exists", error_code="ALREADY_EXISTS", path=p)

        # if node exists but deleted, cannot transition back (deleted -> present disallowed); treat as conflict
        if node and node.get("status") == "deleted":
            _finalize_op(edit_ops, op_row, status="failed", error_code="INVALID_TRANSITION", error_message="cannot recreate a deleted node", node_id=node.get("id"))
            return _err("INVALID_TRANSITION", "Cannot recreate a deleted path", error_code="INVALID_TRANSITION", path=p)

        # create fs_node
        node_id = _gen_id("txnode")
        new_node = {
            "id": node_id,
            "project_id": proj_id,
            "path": p,
            "node_type": "file",
            "status": "present",
            "current_snapshot_id": None,
            "byte_size": None,
            "line_count": None,
            "created_at": now,
            "updated_at": now,
        }

        # create snapshot
        text = file_text
        sha = hashlib.sha256(text.encode("utf-8")).hexdigest()
        bs = _byte_size(text)
        lc = _line_count(text)

        snap_id = _gen_id("txsnap")
        new_snap = {
            "id": snap_id,
            "node_id": node_id,
            "parent_snapshot_id": None,
            "content_text": text,
            "content_sha256": sha,
            "byte_size": bs,
            "line_count": lc,
            "created_at": now,
            "updated_at": now,
        }

        # enforce unique(node_id, content_sha256) trivially satisfied (new node_id)
        new_node["current_snapshot_id"] = snap_id
        new_node["byte_size"] = bs
        new_node["line_count"] = lc

        fs_nodes.append(new_node)
        snaps.append(new_snap)

        # create/update undo pointer
        up = _undo_ptr_by_node(undos, node_id)
        if up is None:
            up = {
                "id": _gen_id("txundo"),
                "node_id": node_id,
                "latest_edit_operation_id": op_row["id"],  # set after finalize, but we already have id
                "status": "available",
                "created_at": now,
                "updated_at": now,
            }
            undos.append(up)
        else:
            up["latest_edit_operation_id"] = op_row["id"]
            up["status"] = "available"
            up["updated_at"] = now

        _save("fs_nodes.json", fs_nodes)
        _save("file_snapshots.json", snaps)
        _save("undo_pointers.json", undos)

        _finalize_op(edit_ops, op_row, status="applied", node_id=node_id, pre_snapshot_id=None, post_snapshot_id=snap_id)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
            "path": p,
            "result": "created",
            "node_id": node_id,
            "snapshot_id": snap_id,
            "byte_size": bs,
            "line_count": lc,
            "operation_id": op_row["id"],
            "latency_ms": latency_ms,
        }

    # common: must resolve to present file node
    if not node or node.get("status") != "present":
        _finalize_op(edit_ops, op_row, status="failed", error_code="NOT_FOUND", error_message="path not found")
        return _err("NOT_FOUND", "Path not found", error_code="NOT_FOUND", path=p)

    if node.get("node_type") != "file":
        _finalize_op(edit_ops, op_row, status="failed", error_code="NOT_A_FILE", error_message="path is not a file", node_id=node.get("id"))
        return _err("VALIDATION_ERROR", "Path is not a file", error_code="NOT_A_FILE", path=p)

    pre_sid = node.get("current_snapshot_id")
    pre_snap = _snapshot_by_id(snaps, pre_sid) if pre_sid else None
    pre_text = pre_snap.get("content_text") if pre_snap and isinstance(pre_snap.get("content_text"), str) else ""
    pre_lc = pre_snap.get("line_count") if pre_snap and isinstance(pre_snap.get("line_count"), int) else _line_count(pre_text)

    if command == "str_replace":
        # occurrences check
        target = old_str
        replacement = new_str_local
        if target == "":
            _finalize_op(edit_ops, op_row, status="failed", error_code="VALIDATION_ERROR", error_message="old_str must not be empty", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("VALIDATION_ERROR", "old_str must not be empty", error_code="VALIDATION_ERROR")

        count = pre_text.count(target)
        if count == 0:
            _finalize_op(edit_ops, op_row, status="failed", error_code="OLD_STR_NOT_FOUND", error_message="old_str not found in file", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("NOT_FOUND", "old_str not found in file", error_code="OLD_STR_NOT_FOUND")
        if count > 1:
            _finalize_op(edit_ops, op_row, status="failed", error_code="OLD_STR_NOT_UNIQUE", error_message="old_str occurs more than once", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("CONFLICT", "old_str occurs more than once", error_code="OLD_STR_NOT_UNIQUE")

        post_text = pre_text.replace(target, replacement, 1)
        if post_text == pre_text:
            _finalize_op(edit_ops, op_row, status="no_change", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=None)
            latency_ms = int((time.time() - t0) * 1000)
            return {
                "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
                "path": p,
                "result": "no_change",
                "node_id": node.get("id"),
                "pre_snapshot_id": pre_sid,
                "post_snapshot_id": None,
                "operation_id": op_row["id"],
                "latency_ms": latency_ms,
            }

        sha = hashlib.sha256(post_text.encode("utf-8")).hexdigest()
        # unique(node_id, content_sha256): if exists, idempotent no_change but still applied? We'll return no_change.
        for s in snaps:
            if s.get("node_id") == node.get("id") and s.get("content_sha256") == sha:
                node["current_snapshot_id"] = s.get("id")
                node["byte_size"] = s.get("byte_size")
                node["line_count"] = s.get("line_count")
                node["updated_at"] = now
                _save("fs_nodes.json", fs_nodes)

                up = _undo_ptr_by_node(undos, node.get("id"))
                if up is None:
                    up = {"id": _gen_id("txundo"), "node_id": node.get("id"), "latest_edit_operation_id": op_row["id"], "status": "available", "created_at": now, "updated_at": now}
                    undos.append(up)
                else:
                    up["latest_edit_operation_id"] = op_row["id"]
                    up["status"] = "available"
                    up["updated_at"] = now
                _save("undo_pointers.json", undos)

                _finalize_op(edit_ops, op_row, status="no_change", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=s.get("id"))
                latency_ms = int((time.time() - t0) * 1000)
                return {
                    "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
                    "path": p,
                    "result": "no_change",
                    "node_id": node.get("id"),
                    "pre_snapshot_id": pre_sid,
                    "post_snapshot_id": s.get("id"),
                    "operation_id": op_row["id"],
                    "latency_ms": latency_ms,
                }

        bs = _byte_size(post_text)
        lc = _line_count(post_text)
        snap_id = _gen_id("txsnap")
        new_snap = {
            "id": snap_id,
            "node_id": node.get("id"),
            "parent_snapshot_id": pre_sid,
            "content_text": post_text,
            "content_sha256": sha,
            "byte_size": bs,
            "line_count": lc,
            "created_at": now,
            "updated_at": now,
        }
        snaps.append(new_snap)
        node["current_snapshot_id"] = snap_id
        node["byte_size"] = bs
        node["line_count"] = lc
        node["updated_at"] = now

        up = _undo_ptr_by_node(undos, node.get("id"))
        if up is None:
            up = {"id": _gen_id("txundo"), "node_id": node.get("id"), "latest_edit_operation_id": op_row["id"], "status": "available", "created_at": now, "updated_at": now}
            undos.append(up)
        else:
            up["latest_edit_operation_id"] = op_row["id"]
            up["status"] = "available"
            up["updated_at"] = now

        _save("file_snapshots.json", snaps)
        _save("fs_nodes.json", fs_nodes)
        _save("undo_pointers.json", undos)

        _finalize_op(edit_ops, op_row, status="applied", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=snap_id)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
            "path": p,
            "result": "replaced",
            "node_id": node.get("id"),
            "pre_snapshot_id": pre_sid,
            "post_snapshot_id": snap_id,
            "byte_size": bs,
            "line_count": lc,
            "operation_id": op_row["id"],
            "latency_ms": latency_ms,
        }

    if command == "insert":
        insert_line_i = int(insert_line)
        if pre_lc == 0:
            # empty file: only insert after line 1 is nonsensical; enforce rule insert_line <= line_count (0)
            _finalize_op(edit_ops, op_row, status="failed", error_code="INVALID_LINE_NUMBER", error_message="cannot insert into empty file using line numbering", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("VALIDATION_ERROR", "invalid insert_line for empty file", error_code="INVALID_LINE_NUMBER")
        if insert_line_i > pre_lc:
            _finalize_op(edit_ops, op_row, status="failed", error_code="INVALID_LINE_NUMBER", error_message="insert_line exceeds file line_count", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("VALIDATION_ERROR", "insert_line exceeds file line_count", error_code="INVALID_LINE_NUMBER")

        # Insert after line insert_line_i
        lines = pre_text.splitlines(True)  # keepends
        idx = insert_line_i  # after line N means insertion at list index N
        post_text = "".join(lines[:idx]) + new_str + "".join(lines[idx:])

        if post_text == pre_text:
            _finalize_op(edit_ops, op_row, status="no_change", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=None)
            latency_ms = int((time.time() - t0) * 1000)
            return {
                "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
                "path": p,
                "result": "no_change",
                "node_id": node.get("id"),
                "pre_snapshot_id": pre_sid,
                "post_snapshot_id": None,
                "operation_id": op_row["id"],
                "latency_ms": latency_ms,
            }

        sha = hashlib.sha256(post_text.encode("utf-8")).hexdigest()
        for s in snaps:
            if s.get("node_id") == node.get("id") and s.get("content_sha256") == sha:
                node["current_snapshot_id"] = s.get("id")
                node["byte_size"] = s.get("byte_size")
                node["line_count"] = s.get("line_count")
                node["updated_at"] = now
                _save("fs_nodes.json", fs_nodes)

                up = _undo_ptr_by_node(undos, node.get("id"))
                if up is None:
                    up = {"id": _gen_id("txundo"), "node_id": node.get("id"), "latest_edit_operation_id": op_row["id"], "status": "available", "created_at": now, "updated_at": now}
                    undos.append(up)
                else:
                    up["latest_edit_operation_id"] = op_row["id"]
                    up["status"] = "available"
                    up["updated_at"] = now
                _save("undo_pointers.json", undos)

                _finalize_op(edit_ops, op_row, status="no_change", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=s.get("id"))
                latency_ms = int((time.time() - t0) * 1000)
                return {
                    "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
                    "path": p,
                    "result": "no_change",
                    "node_id": node.get("id"),
                    "pre_snapshot_id": pre_sid,
                    "post_snapshot_id": s.get("id"),
                    "operation_id": op_row["id"],
                    "latency_ms": latency_ms,
                }

        bs = _byte_size(post_text)
        lc = _line_count(post_text)
        snap_id = _gen_id("txsnap")
        new_snap = {
            "id": snap_id,
            "node_id": node.get("id"),
            "parent_snapshot_id": pre_sid,
            "content_text": post_text,
            "content_sha256": sha,
            "byte_size": bs,
            "line_count": lc,
            "created_at": now,
            "updated_at": now,
        }
        snaps.append(new_snap)
        node["current_snapshot_id"] = snap_id
        node["byte_size"] = bs
        node["line_count"] = lc
        node["updated_at"] = now

        up = _undo_ptr_by_node(undos, node.get("id"))
        if up is None:
            up = {"id": _gen_id("txundo"), "node_id": node.get("id"), "latest_edit_operation_id": op_row["id"], "status": "available", "created_at": now, "updated_at": now}
            undos.append(up)
        else:
            up["latest_edit_operation_id"] = op_row["id"]
            up["status"] = "available"
            up["updated_at"] = now

        _save("file_snapshots.json", snaps)
        _save("fs_nodes.json", fs_nodes)
        _save("undo_pointers.json", undos)

        _finalize_op(edit_ops, op_row, status="applied", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=snap_id)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
            "path": p,
            "result": "inserted",
            "node_id": node.get("id"),
            "pre_snapshot_id": pre_sid,
            "post_snapshot_id": snap_id,
            "byte_size": bs,
            "line_count": lc,
            "operation_id": op_row["id"],
            "latency_ms": latency_ms,
        }

    if command == "undo_edit":
        up = _undo_ptr_by_node(undos, node.get("id"))
        if up is None or up.get("status") == "empty" or not up.get("latest_edit_operation_id"):
            # record as no_change
            if up is None:
                up = {
                    "id": _gen_id("txundo"),
                    "node_id": node.get("id"),
                    "latest_edit_operation_id": None,
                    "status": "empty",
                    "created_at": now,
                    "updated_at": now,
                }
                undos.append(up)
                _save("undo_pointers.json", undos)
            _finalize_op(edit_ops, op_row, status="no_change", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=None)
            latency_ms = int((time.time() - t0) * 1000)
            return {
                "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
                "path": p,
                "result": "no_change",
                "reason": "undo_empty",
                "node_id": node.get("id"),
                "operation_id": op_row["id"],
                "latency_ms": latency_ms,
            }

        latest_op = _edit_op_by_id(edit_ops, up.get("latest_edit_operation_id"))
        if latest_op is None:
            # pointer corrupt; make empty
            up["latest_edit_operation_id"] = None
            up["status"] = "empty"
            up["updated_at"] = now
            _save("undo_pointers.json", undos)
            _finalize_op(edit_ops, op_row, status="failed", error_code="INTERNAL_ERROR", error_message="undo pointer references missing edit operation", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("INTERNAL_ERROR", "Undo pointer is invalid")

        # We only undo applied mutating operations
        latest_post = latest_op.get("post_snapshot_id")
        latest_pre = latest_op.get("pre_snapshot_id")

        # Sanity: current should match latest_post if present; if not, still attempt revert to latest_pre.
        if latest_op.get("command") == "create" and latest_pre is None:
            # Undo create => delete node (present -> deleted)
            node["status"] = "deleted"
            node["current_snapshot_id"] = None
            node["byte_size"] = None
            node["line_count"] = None
            node["updated_at"] = now

            # update pointer to previous op in chain: none after undoing create
            up["latest_edit_operation_id"] = None
            up["status"] = "empty"
            up["updated_at"] = now

            _save("fs_nodes.json", fs_nodes)
            _save("undo_pointers.json", undos)

            _finalize_op(edit_ops, op_row, status="applied", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=None)
            latency_ms = int((time.time() - t0) * 1000)
            return {
                "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
                "path": p,
                "result": "undone",
                "node_id": node.get("id"),
                "reverted_to_snapshot_id": None,
                "operation_id": op_row["id"],
                "latency_ms": latency_ms,
            }

        # revert snapshot pointer
        if latest_pre is None:
            # No pre snapshot but not create => inconsistent history
            _finalize_op(edit_ops, op_row, status="failed", error_code="INTERNAL_ERROR", error_message="cannot undo: missing pre_snapshot_id", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("INTERNAL_ERROR", "Cannot undo: missing pre_snapshot_id")

        if not _snapshot_by_id(snaps, latest_pre):
            _finalize_op(edit_ops, op_row, status="failed", error_code="INTERNAL_ERROR", error_message="cannot undo: pre_snapshot_id missing", node_id=node.get("id"), pre_snapshot_id=pre_sid)
            return _err("INTERNAL_ERROR", "Cannot undo: referenced snapshot missing")

        node["current_snapshot_id"] = latest_pre
        pre_snap2 = _snapshot_by_id(snaps, latest_pre)
        node["byte_size"] = pre_snap2.get("byte_size")
        node["line_count"] = pre_snap2.get("line_count")
        node["updated_at"] = now
        _save("fs_nodes.json", fs_nodes)

        # walk back the chain: previous operation is the one whose post_snapshot_id == latest_pre
        prev_op_id = None
        for o in edit_ops:
            if o.get("node_id") == node.get("id") and o.get("status") == "applied" and o.get("post_snapshot_id") == latest_pre:
                prev_op_id = o.get("id")
                break

        if prev_op_id is None:
            up["latest_edit_operation_id"] = None
            up["status"] = "empty"
        else:
            up["latest_edit_operation_id"] = prev_op_id
            up["status"] = "available"
        up["updated_at"] = now
        _save("undo_pointers.json", undos)

        _finalize_op(edit_ops, op_row, status="applied", node_id=node.get("id"), pre_snapshot_id=pre_sid, post_snapshot_id=latest_pre)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "project": {"id": proj_id, "root_path": project.get("root_path"), "status": project.get("status")},
            "path": p,
            "result": "undone",
            "node_id": node.get("id"),
            "pre_snapshot_id": pre_sid,
            "post_snapshot_id": latest_pre,
            "operation_id": op_row["id"],
            "latency_ms": latency_ms,
        }

    # Should never reach
    _finalize_op(edit_ops, op_row, status="failed", error_code="INTERNAL_ERROR", error_message="unhandled command")
    return _err("INTERNAL_ERROR", "Unhandled command")

def projects_list(status=None, name_contains=None, limit=None, cursor=None, **_extra):
