        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    projects = _load("projects.json")
    edit_ops = _load("edit_operations.json")

    def _log(status_str, msg=None):
        # Record every call as one edit_operations row (read tools still must record service dynamics).
        # Use command 'view' with synthetic path marker.
        op = {
            "id": "op_list_" + os.urandom(8).hex(),
            "project_id": (projects[0]["id"] if projects else "unknown"),
            "node_id": None,
            "command": "view",
            "path": "/__projects_list__",
            "description": "projects_list",
            "file_text": None,
            "old_str": None,
            "new_str": None,
            "insert_line": None,
            "view_range": None,
            "pre_snapshot_id": None,
            "post_snapshot_id": None,
            "status": status_str,
            "error_code": ("VALIDATION_ERROR" if status_str == "failed" else None),
            "error_message": msg,
            "created_at": now,
            "updated_at": now
        }
        edit_ops.append(op)
        try:
            _save("edit_operations.json", edit_ops)
        except Exception:
            pass
        return op

    if status is not None and status not in ("active", "readonly", "disabled"):
        op = _log("failed", "Invalid status filter")
        return _err("VALIDATION_ERROR", "Invalid status filter", operation=op)
    if name_contains is not None and not isinstance(name_contains, str):
        op = _log("failed", "name_contains must be a string")
        return _err("VALIDATION_ERROR", "name_contains must be a string", operation=op)
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        op = _log("failed", "limit must be an integer between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", operation=op)
    if cursor is not None and not isinstance(cursor, str):
        op = _log("failed", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string", operation=op)

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                op = _log("failed", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor", operation=op)
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            op = _log("failed", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor", operation=op)

    rows = projects[:]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if name_contains:
        needle = name_contains.lower()
        rows = [r for r in rows if isinstance(r.get("name"), str) and needle in r["name"].lower()]

    rows.sort(key=lambda r: (r.get("created_at", ""), r.get("id", "")))

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    op = _log("applied", None)
    latency_ms = int((time.time() - t0) * 1000)
    # update stored op latency? schema doesn't have latency; leave as is.

    return {
        "operation": op,
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

