            op = _log("failed", "name must be 1..200 characters")
            return _err("VALIDATION_ERROR", "name must be 1..200 characters", operation=op)

    if status is not None and status not in ("active", "readonly", "disabled"):
        op = _log("failed", "Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status", operation=op)

    pr = None
    for r in projects:
        if r.get("id") == id:
            pr = r
            break
    if pr is None:
        op = _log("failed", "Project not found")
        return _err("NOT_FOUND", "Project not found", operation=op)

    # Enforce project constraints: length(name) between 1 and 120 (schema constraint), even if tool allows 200.
    if name is not None and not (1 <= len(name) <= 120):
        op = _log("failed", "name must be 1..120 characters (service constraint)", project_id=pr.get("id"))
        return _err("VALIDATION_ERROR", "name must be 1..120 characters", operation=op)

    # Unique(root_path) untouched here; root_path isn't mutable by tool.
    # Lifecycle transitions for status
    if status is not None and status != pr.get("status"):
        cur = pr.get("status")
        allowed = {
            "active": ("readonly", "disabled"),
            "readonly": ("active", "disabled"),
            "disabled": ()
        }.get(cur, ())
        if status not in allowed:
            op = _log("failed", f"Illegal status transition {cur}->{status}", project_id=pr.get("id"))
            return _err("INVALID_TRANSITION", "Illegal status transition", operation=op, from_status=cur, to_status=status)

    # Ensure at least one field changes
    changed = False
    if name is not None and name != pr.get("name"):
        pr["name"] = name
        changed = True
    if status is not None and status != pr.get("status"):
        pr["status"] = status
        changed = True

    if not changed:
        # No success without effect for mutation
        op = _log("failed", "No fields changed", project_id=pr.get("id"))
        return _err("CONFLICT", "No fields changed", operation=op)

    pr["updated_at"] = now
    try:
        _save("projects.json", projects)
    except Exception:
        op = _log("failed", "Failed to persist project update", project_id=pr.get("id"))
        return _err("INTERNAL_ERROR", "Failed to persist project update", operation=op)

