    projects = _load("projects.json")
    fs_nodes = _load("fs_nodes.json")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        return _err("NOT_FOUND", "Project not found", project_id=project_id)

    filters = {"path_prefix": path_prefix, "node_type": node_type, "status": status, "limit": limit}

    cur = _parse_cursor(cursor) if cursor is not None else None
    if cursor is not None and cur is None:
        return _err("VALIDATION_ERROR", "Invalid cursor")
    if cur is not None:
        if cur.get("project_id") != project_id:
            return _err("VALIDATION_ERROR", "Cursor does not match project_id")
        if cur.get("filters") != filters:
            return _err("VALIDATION_ERROR", "Cursor does not match current filters")
        last = cur.get("last")
        if last is not None and (not isinstance(last, str) or "|" not in last):
            return _err("VALIDATION_ERROR", "Invalid cursor state")
    else:
        last = None

    # Filter rows
    rows = []
    prefix = path_prefix
    for n in fs_nodes:
        if not isinstance(n, dict):
            continue
        if n.get("project_id") != project_id:
            continue
        if prefix is not None:
            p = n.get("path")
            if not isinstance(p, str):
                continue
            if not (p == prefix or p.startswith(prefix.rstrip("/") + "/") or p.startswith(prefix)):
                # Using a tolerant check; exact prefix semantics are "under that prefix".
                continue
            # Ensure "under prefix" for typical absolute paths:
            if p != prefix and not p.startswith(prefix.rstrip("/") + "/"):
                continue
        if node_type is not None and n.get("node_type") != node_type:
            continue
        if status is not None and n.get("status") != status:
            continue
        rows.append(n)

    # Sort by path then id for stable pagination
    def _k(n):
        return (n.get("path") or "", n.get("id") or "")

    rows.sort(key=_k)

    # Apply cursor pagination (exclusive)
    if last is not None:
        # last key is "path|id"
        try:
            last_path, last_id = last.split("|", 1)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor state")
        def _gt(n):
            kp = n.get("path") or ""
            ki = n.get("id") or ""
            return (kp, ki) > (last_path, last_id)
        rows = [r for r in rows if _gt(r)]

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        lp = page[-1].get("path") or ""
        li = page[-1].get("id") or ""
        next_cursor = _make_cursor(f"{lp}|{li}", project_id, filters)

    latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)

    # No request-log collection declared; nothing to persist for usage/audit beyond normal reads.
    return {
        "nodes": page,
        "metadata": {
            "project_id": project_id,
            "count": len(page),
            "total_matched": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
            "timestamp": _now(),
        },
    }

def edit_operations_list(project_id=None, node_id=None, path=None, command=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0451000" if __import__("os").path.isdir("./environment_mix/0451000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(s2)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("t") != "edit_operations_list":
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if "last" not in obj or "filters" not in obj:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return obj

    def _make_cursor(last_key, filters):
        obj = {"v": 1, "t": "edit_operations_list", "last": last_key, "filters": filters}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate filters
    if project_id is not None and (not isinstance(project_id, str) or not project_id):
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string")
    if node_id is not None and (not isinstance(node_id, str) or not node_id):
        return _err("VALIDATION_ERROR", "node_id must be a non-empty string")
    if path is not None and (not isinstance(path, str) or not path.startswith("/")):
        return _err("VALIDATION_ERROR", "path must be an absolute path starting with '/'")
    if command is not None and command not in ("view", "create", "str_replace", "insert", "undo_edit"):
        return _err("VALIDATION_ERROR", "command must be one of: view, create, str_replace, insert, undo_edit")
    if status is not None and status not in ("applied", "no_change", "failed"):
        return _err("VALIDATION_ERROR", "status must be one of: applied, no_change, failed")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb
    if ca and cb and not (cb > ca):
        return _err("VALIDATION_ERROR", "created_before must be strictly greater than created_after when both are provided")

    cur = None
    if cursor is not None:
        cur = _parse_cursor(cursor)
        if isinstance(cur, dict) and "error" in cur:
            return cur

    # Load data
    ops = _load("edit_operations.json")
    projects = _load("projects.json")
    nodes = _load("fs_nodes.json")
    snaps = _load("file_snapshots.json")

    # Validate referenced ids if provided
    if project_id is not None:
        if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
            return _err("NOT_FOUND", "project_id not found")
    if node_id is not None:
        if not any(isinstance(n, dict) and n.get("id") == node_id for n in nodes):
            return _err("NOT_FOUND", "node_id not found")

    # Apply cursor filters consistency
    filters = {
        "project_id": project_id,
        "node_id": node_id,
        "path": path,
        "command": command,
        "status": status,
        "created_after": created_after,
        "created_before": created_before
    }
    if cur is not None:
        if cur.get("filters") != filters:
            return _err("VALIDATION_ERROR", "cursor does not match the current filters")

    # Filter
    rows = []
    for o in ops if isinstance(ops, list) else []:
        if not isinstance(o, dict):
            continue
        if project_id is not None and o.get("project_id") != project_id:
            continue
        if node_id is not None and o.get("node_id") != node_id:
            continue
        if path is not None and o.get("path") != path:
            continue
        if command is not None and o.get("command") != command:
            continue
        if status is not None and o.get("status") != status:
            continue
        oca = o.get("created_at")
        if (ca or cb) and isinstance(oca, str):
            oca2 = oca[:-1] + "+00:00" if oca.endswith("Z") else oca
            try:
                odt = datetime.datetime.fromisoformat(oca2)
            except ValueError:
                odt = None
            if odt is not None:
                if ca and not (odt > ca):
                    continue
                if cb and not (odt < cb):
                    continue
        elif (ca or cb):
            continue
        rows.append(o)

    # Sort by created_at desc then id desc
    def _sort_key(o):
        s = o.get("created_at") if isinstance(o.get("created_at"), str) else ""
        oid = o.get("id") if isinstance(o.get("id"), str) else ""
        return (s, oid)

    rows.sort(key=_sort_key, reverse=True)

    # Pagination using cursor "last" = {"created_at":..., "id":...}
    if cur is not None:
        last = cur.get("last")
        if not isinstance(last, dict) or "created_at" not in last or "id" not in last:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        last_ca = last.get("created_at")
        last_id = last.get("id")
        # find start index after last key
        paged = []
        passed = False
        for r in rows:
            if not passed:
                if r.get("created_at") == last_ca and r.get("id") == last_id:
                    passed = True
                continue
            paged.append(r)
        rows = paged

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last_row = page[-1]
        next_cursor = _make_cursor({"created_at": last_row.get("created_at"), "id": last_row.get("id")}, filters)

    # OBSERVABLE DYNAMICS: every call appends an audit edit_operation row of command=view on path="/__audit__/edit_operations_list"
    # This is the only audit collection available; record the list call without pretending a mutation occurred.
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    audit_row = {
        "id": f"txop_{uuid.uuid4().hex}" if False else None
    }
    # can't import uuid at top due to contract style; do minimal safe generation with base64 timestamp+pid
    # but must not raise; if we can't, skip id generation and don't save (to avoid corrupting store)
    try:
        import uuid as _uuid
        audit_id = f"txop_{_uuid.uuid4().hex}"
        audit_row = {
            "id": audit_id,
            "project_id": project_id if project_id is not None else (projects[0]["id"] if projects else "unknown"),
            "node_id": node_id,
            "command": "view",
            "path": "/__audit__/edit_operations_list",
            "description": "list edit operations",
            "file_text": None,
            "old_str": None,
            "new_str": None,
            "insert_line": None,
            "view_range": None,
            "pre_snapshot_id": None,
            "post_snapshot_id": None,
            "status": "applied",
            "error_code": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(audit_row)
        _save("edit_operations.json", ops)
    except Exception:
        # do not fail the list call if auditing can't be persisted
        pass

    return {
        "data": page,
        "meta": {
            "limit": limit,
            "total": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
